def solve(grid):
    """Find rectangular frames of 2s, fill interior (except center) with 8s"""
    h, w = len(grid), len(grid[0])

    # Find all valid frames (deduplicate by bounding box)
    frames = []
    seen = set()
    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] != 2:
                continue
            for r2 in range(r1 + 2, h):
                for c2 in range(c1 + 2, w):
                    # Validate complete border of 2s
                    top_ok = all(grid[r1][c] == 2 for c in range(c1, c2+1))
                    bottom_ok = all(grid[r2][c] == 2 for c in range(c1, c2+1))
                    left_ok = all(grid[r][c1] == 2 for r in range(r1, r2+1))
                    right_ok = all(grid[r][c2] == 2 for r in range(r1, r2+1))

                    if top_ok and bottom_ok and left_ok and right_ok:
                        key = (r1, c1, r2, c2)
                        if key not in seen:
                            seen.add(key)
                            frames.append((r1, c1, r2, c2))

    # Create result
    result = [row[:] for row in grid]

    # Apply transformation (order doesn't matter since interiors don't overlap borders)
    for r1, c1, r2, c2 in frames:
        cr, cc = (r1+r2)//2, (c1+c2)//2

        for r in range(r1+1, r2):
            for c in range(c1+1, c2):
                # Skip center
                if r == cr and c == cc:
                    continue
                # Fill interior
                result[r][c] = 8

    return result

